package com.primehr.performancemanagement;
import com.primehr.performancemanagement.domain.PerformanceMidCycleReview;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class PerformanceMidCycleReviewTest{
 @Test void submittedReviewRequiresEmployeeAcknowledgmentOrReasonedAuthorizedClosure(){var review=new PerformanceMidCycleReview("A","CASE",2,1,0,"Supervisor narrative",null,true,"Targets require formal amendment");review.submit("SUP",Instant.now());assertThat(review.getStatus()).isEqualTo(PerformanceMidCycleReview.Status.SUBMITTED);review.acknowledge("EMP","Receipt acknowledged",Instant.now());assertThat(review.getStatus()).isEqualTo(PerformanceMidCycleReview.Status.ACKNOWLEDGED);assertThat(review.getEmployeeNarrative()).isEqualTo("Receipt acknowledged");}
 @Test void amendmentRecommendationAndClosureRequireReasons(){assertThatThrownBy(()->new PerformanceMidCycleReview("A","CASE",0,0,0,"Narrative",null,true,null)).isInstanceOf(IllegalArgumentException.class);var review=new PerformanceMidCycleReview("A","CASE",0,0,0,"Narrative",null,false,null);review.submit("SUP",Instant.now());assertThatThrownBy(()->review.closeWithoutAcknowledgment(null)).isInstanceOf(IllegalArgumentException.class);review.closeWithoutAcknowledgment("Employee unavailable after documented attempts");assertThat(review.getStatus()).isEqualTo(PerformanceMidCycleReview.Status.CLOSED_WITHOUT_ACKNOWLEDGMENT);}
}
